// ✅ Valida el payload del aviso y aplica un límite de frecuencia simple.
// No usa require(). Devuelve siempre un solo item con { valido, codigo, mensaje, datos }.
const cfg = $('Configurar Aviso').first().json;
const req = $('Recibir Aviso Programa').first().json;

let body = req.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = null; }
}
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return [{ json: { valido: false, codigo: 400, mensaje: 'El cuerpo debe ser un objeto JSON.', errores: ['body'] } }];
}

const texto = (v, max) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const RAMAS = ['manada', 'tropa', 'comunidad', 'clan', 'grupal'];
const TIPOS = ['unidad', 'grupal'];
const ORIGENES = (cfg.origenes_permitidos || 'github-pages,servidor,prueba').split(',').map(s => s.trim());
const errores = [];

const titulo = texto(body.titulo, 160);
const autor = texto(body.autor, 80);
const tipo = texto(body.tipo, 10).toLowerCase();
let rama = texto(body.rama, 20).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const fecha = texto(body.fecha, 10);
const fechaFin = texto(body.fecha_fin, 10);
const origen = texto(body.origen, 20).toLowerCase();
const verificado = body.verificado === true;

if (!titulo) errores.push('titulo');
if (!autor) errores.push('autor');
if (!TIPOS.includes(tipo)) errores.push('tipo (unidad | grupal)');
if (tipo === 'grupal') rama = 'grupal'; // decisión: la actividad grupal se marca "Grupal"
if (!RAMAS.includes(rama)) errores.push('rama (manada | tropa | comunidad | clan)');
if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha) || isNaN(Date.parse(fecha + 'T00:00:00Z'))) errores.push('fecha (AAAA-MM-DD)');
if (fechaFin && !/^\d{4}-\d{2}-\d{2}$/.test(fechaFin)) errores.push('fecha_fin (AAAA-MM-DD)');
if (!ORIGENES.includes(origen)) errores.push('origen (' + ORIGENES.join(' | ') + ')');
if (typeof body.verificado !== 'boolean') errores.push('verificado (true | false)');

if (errores.length) {
  return [{ json: { valido: false, codigo: 400, mensaje: 'Payload inválido.', errores } }];
}

// ⏱️ Límite de frecuencia (solo cuenta en ejecuciones de producción: workflow activo).
const limite = Number(cfg.max_avisos_por_hora) || 20;
const estado = $getWorkflowStaticData('global');
const ahora = Date.now();
estado.avisos = (estado.avisos || []).filter(t => ahora - t < 3600 * 1000);
if (estado.avisos.length >= limite) {
  return [{ json: { valido: false, codigo: 429, mensaje: 'Demasiados avisos en la última hora. Intenta más tarde.', errores: ['limite'] } }];
}
estado.avisos.push(ahora);

const RAMA_NOMBRE = { manada: 'Manada', tropa: 'Tropa', comunidad: 'Comunidad', clan: 'Clan', grupal: 'Grupal' };
return [{
  json: {
    valido: true,
    codigo: 200,
    datos: {
      titulo, autor, tipo, rama, rama_nombre: RAMA_NOMBRE[rama],
      fecha, fecha_fin: fechaFin || null, origen, verificado,
      url: /^https:\/\//.test(String(body.url || '')) ? texto(body.url, 300) : '',
      recibido: new Date(ahora).toISOString(),
    },
  },
}];

// 💌 Arma el asunto y el cuerpo HTML del correo. Escapa todo lo que viene del navegador.
const cfg = $('Configurar Aviso').first().json;
const d = $json.datos || {};
const esc = t => String(t ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const COLORES = { manada: '#F2B705', tropa: '#1E8C3A', comunidad: '#1F5FAD', clan: '#B40D15', grupal: '#5B2C83' };
const color = COLORES[d.rama] || '#5B2C83';
const fechaTxt = (f) => {
  if (!f) return '';
  try {
    return new Date(f + 'T12:00:00Z').toLocaleDateString('es-VE', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' });
  } catch (e) { return f; }
};
const fechas = d.fecha_fin && d.fecha_fin !== d.fecha ? `${fechaTxt(d.fecha)} → ${fechaTxt(d.fecha_fin)}` : fechaTxt(d.fecha);
const sello = d.verificado
  ? '<span style="background:#e6f6ea;color:#1f7a3a;padding:3px 10px;border-radius:12px;font-size:12px;font-weight:700">✔ Verificado</span>'
  : '<span style="background:#fff4d6;color:#8a5a00;padding:3px 10px;border-radius:12px;font-size:12px;font-weight:700">Sin verificar</span>';
const fila = (k, v) => `<tr><td style="padding:6px 0;color:#777;width:120px;vertical-align:top">${k}</td><td style="padding:6px 0;color:#222;font-weight:600">${v}</td></tr>`;
const boton = d.url
  ? `<p style="margin:22px 0 4px"><a href="${esc(d.url)}" style="background:${color};color:#fff;text-decoration:none;padding:10px 18px;border-radius:8px;font-weight:700">📂 Abrir el programa</a></p>`
  : `<p style="margin:22px 0 4px"><a href="${esc(cfg.url_sitio)}" style="background:${color};color:#fff;text-decoration:none;padding:10px 18px;border-radius:8px;font-weight:700">⚜️ Ir a la Ficha Técnica</a></p>`;

const html = `<!DOCTYPE html><html lang="es"><body style="margin:0;background:#f3f0f7;font-family:Montserrat,Arial,sans-serif">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="padding:24px 12px"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#fff;border-radius:14px;overflow:hidden;box-shadow:0 2px 10px rgba(0,0,0,.08)">
<tr><td style="background:${color};padding:18px 24px;color:#fff">
  <div style="font-size:12px;letter-spacing:1px;text-transform:uppercase;opacity:.9">⚜️ ${esc(cfg.nombre_grupo)}</div>
  <div style="font-size:20px;font-weight:800;margin-top:4px">📚 Nuevo programa · ${esc(d.rama_nombre)}</div>
</td></tr>
<tr><td style="padding:22px 24px">
  <h2 style="margin:0 0 10px;font-size:18px;color:#222">${esc(d.titulo)}</h2>
  <p style="margin:0 0 14px">${sello}</p>
  <table role="presentation" cellpadding="0" cellspacing="0" style="font-size:14px;width:100%">
    ${fila('📅 Fecha', esc(fechas))}
    ${fila('🏕️ Tipo', d.tipo === 'grupal' ? 'Grupal' : 'Unidad')}
    ${fila('✍️ Autor', esc(d.autor))}
    ${fila('🌐 Origen', esc(d.origen))}
  </table>
  ${boton}
</td></tr>
<tr><td style="padding:14px 24px;background:#faf8fc;color:#999;font-size:11px">
  Aviso automático de la Ficha Técnica Scout. Recibido ${esc(d.recibido)}.<br>
  No contiene datos personales de jóvenes. Si no esperabas este correo, avísale al administrador.
</td></tr>
</table></td></tr></table></body></html>`;

const asunto = `📚 Nuevo programa ${d.rama_nombre}: ${d.titulo}`.slice(0, 180);
return [{ json: { ...d, asunto, html, destinatario: cfg.destinatario } }];

// 🚨 Resume el error global (Error Trigger) para la alerta.
const e = $json || {};
const exec = e.execution || {};
const wf = e.workflow || {};
return [{
  json: {
    workflow: wf.name || 'Scout — Aviso de programa nuevo',
    nodo: exec.lastNodeExecuted || exec.error?.node?.name || 'desconocido',
    mensaje: String(exec.error?.message || 'Error sin mensaje').slice(0, 500),
    ejecucion_id: exec.id || '',
    url: exec.url || '',
    fecha: new Date().toISOString(),
  },
}];
